parameters.value:
string method = chs("pointcountmethod");
if(method == "numpts")
    i@__numpts = chi("npts");
else if(method != "density")
{
    // sqrt(3) / 6
    float n = f@__area * 0.28867513459481287 * ch("coverage");
    if(method == "size")
    {
        float a = ch("minradius");
        float b = ch("maxradius");
        float u = ch("uniformscale");
        a *= u;
        b *= u;
        i@__numpts = int(n / (a * b));
    }
    else
        i@__numpts = int(n * 4);
}

float scale = 1;
float minpscale = ch("minradius");

// adjust pscale downwards to avoid overlap
int npts = npoints(0);
int closepts[] = pcfind_radius(0, "P", "__pscale", 1.0f, v@P, f@__pscale, npts);
foreach(int pt; closepts)
{
    if(pt == @ptnum)
        continue;

    vector p1 = point(0, "P", pt);
    float pscale1 = point(0, "__pscale", pt);

    float dist = length(p1 - v@P);
    float s = dist / (f@__pscale + pscale1);
    if(s < scale)
        scale = s;
}
npts = npoints(1);
closepts = pcfind_radius(1, "P", "__pscale", 1.0f, v@P, f@__pscale, npts);
foreach(int pt; closepts)
{
    vector p1 = point(1, "P", pt);
    float pscale1 = point(1, "__pscale", pt);

    float dist = length(p1 - v@P);
    float s = (dist - pscale1) / f@__pscale;
    if(s < scale)
        scale = s;
}

scale *= f@__pscale;
if(scale < minpscale)
    scale = minpscale;
f@__pscale = scale;

float scale = 1;
float minpscale = ch("minradius");

int npts = npoints(0);
int closepts[] = pcfind_radius(0, "P", "__pscale", 1.0f, v@P, f@__pscale, npts);
foreach(int pt; closepts)
{
    if(pt == @ptnum)
        continue;

    vector p1 = point(0, "P", pt);
    float pscale1 = point(0, "__pscale", pt);

    float dist = length(p1 - v@P);
    float pscale_sum = f@__pscale + pscale1;
    float s = dist / pscale_sum;
    if(s < scale)
        scale = s;
}
npts = npoints(1);
closepts = pcfind_radius(1, "P", "__pscale", 1.0f, v@P, f@__pscale, npts);
foreach(int pt; closepts)
{
    vector p1 = point(1, "P", pt);
    float pscale1 = point(1, "__pscale", pt);

    float dist = length(p1 - v@P);
    float s = (dist - pscale1) / f@__pscale;
    if(s < scale)
        scale = s;
}

scale *= f@__pscale;
if(scale < (1 - ch("overlaptolerance")) * minpscale)
    removepoint(geoself(), @ptnum);

int pr = i@__sourceprim;
vector uvw = v@__sourceprimuv;

if(haspointattrib(1, "pscale") || hasvertexattrib(1, "pscale"))
    f@__pscale *= primuv(1, "pscale", pr, uvw);

p@__orient = set(0, 0, 0, 1);
if(haspointattrib(1, "orient") || hasvertexattrib(1, "orient"))
    p@__orient = primuv(1, "orient", pr, uvw);

f@__blend_attrib = 1.0;
if (chi("scaleblendbyattrib"))
    f@__blend_attrib = primuv(1, chs("blendattribute"), pr, uvw);

f@__cone_attrib = 1.0;
if (chi("scaleconebyattrib"))
    f@__cone_attrib = primuv(1, chs("coneattribute"), pr, uvw);

f@__basenml_attrib = 1.0;
if (chi("scalebasenmlbyattrib"))
    f@__basenml_attrib = primuv(1, chs("basenmlattribute"), pr, uvw);

v@__blend_target_attrib = set(0,1,0);
if (chs("blendtarget") == "attribute")
    v@__blend_target_attrib = primuv(1, chs("blendtargetattribute"), pr, uvw);

v@__up_target_attrib = set(1,0,0);
if (chs("upbias") == "attribute")
    v@__up_target_attrib = primuv(1, chs("upbiasattrib"), pr, uvw);

f@__density = 1;
if(chs("coveragescalemode") == "attrib")
{
    string attrib = strip(chs("coverageattrib"));
    float val = point(0, attrib, @ptnum);
    f@__density = clamp(val, 0.0, 1.0);
}

float a = ch("minradius");
float b = ch("maxradius");
float u = ch("uniformscale");
f@__pscale = a * b * u / (b - rand(@ptnum) * (b - a));

// Parameters to modify:
// Location Attribute - pos
// Element Size - elementsize
// Offset - offset

if(chi("outputradiusattrib"))
    setpointattrib(0, chs("radiusattrib"), @ptnum, f@__pscale);

vector normal = normalize(@N);

// Rotation around normal

vector4 orient;
int outputorientattrib = chi("outputorientattrib");
if (outputorientattrib)
{
    vector orig_nml;
    string normalbiasmenu = chs("initnormal");
    if (normalbiasmenu == "x")
        orig_nml = set(1,0,0);
    else if (normalbiasmenu == "y")
        orig_nml = set(0,1,0);
    else if (normalbiasmenu == "z")
        orig_nml = set(0,0,1);
    else // if (normalbiasmenu == "custom")
        orig_nml = normalize(chv("initnormalcustom"));

    orient = dihedral(orig_nml, normal);

    vector init_up_vec;
    string init_up = chs("initup");
    if (init_up == "x")
        init_up_vec = set(1,0,0);
    else if (init_up == "y")
        init_up_vec = set(0,1,0);
    else if (init_up == "z")
        init_up_vec = set(0,0,1);
    else // if (init_up == "custom")
        init_up_vec = normalize(chv("initupcustom"));

    string upbias = chs("upbias");
    if (upbias != "nobias")
    {
        vector bias;
        if (upbias == "x")
            bias = set(1,0,0);
        else if (upbias == "y")
            bias = set(0,1,0);
        else if (upbias == "z")
            bias = set(0,0,1);
        else if (upbias == "custom")
            bias = normalize(chv("upbiascustom"));
        else // if (upbias == "attribute")
            bias = normalize(v@__up_target_attrib);

        vector up = qrotate(orient, init_up_vec);
        vector bias_proj = dot(bias, normal) * normal;
        vector bias_perp = bias - bias_proj;
        // Bias Perp is in span{up, out}
        orient = qmultiply(dihedral(up, bias_perp), orient);
    }

    float perprot = radians(ch("perprot"));
    perprot *= f@__basenml_attrib;

    float perprotrandmin = radians(ch("perprotrandmin"));
    float perprotrandmax = radians(ch("perprotrandmax"));
    float r = rand(2 * @ptnum);

    if(chi("useperprotramp"))
        r = chramp("perprotramp", r);

    float perprotrand = lerp(perprotrandmin, perprotrandmax, r);

    if (chi("roundperprot"))
    {
        float step = radians(ch("perprandstep"));
        perprotrand = step * rint(perprotrand/step);
        perprotrand = max(perprotrand, perprotrandmin);
        perprotrand = min(perprotrand, perprotrandmax);
    }

    perprot += perprotrand;
    orient = qmultiply(quaternion(perprot, normal), orient);
}

