    f@__spacing *= val;
}
if(chi("useminspacing"))
{
    float limit = ch("minspacing");
    if(f@__spacing < limit)
        f@__spacing = limit;
}
f@__density /= f@__spacing * f@__spacing;

int test_overlap(const int input; const vector P; const int curpt; const float pscale; const float tol)
{
    int npts = npoints(input);
    int closepts[] = pcfind_radius(input, "P", "__pscale", 1.0f, P, pscale, npts);
    foreach(int pt; closepts)
    {
        if(input == 0 && pt == curpt)
            continue;

        vector p1 = point(input, "P", pt);
        float pscale1 = point(input, "__pscale", pt);
        if(length(p1 - P) - pscale1 < (1 - tol) * pscale)
            return 1;
    }
    return 0;
}

float tol = ch("overlaptolerance");
if(test_overlap(0, v@P, @ptnum, f@__pscale, tol) == 1
    || test_overlap(1, v@P, @ptnum, f@__pscale, tol) == 1)
    removepoint(geoself(), @ptnum);

float a = ch("minradius");
float b = ch("maxradius");
float u = ch("uniformscale");
a *= u;
b *= u;
f@__pscale = a * b / (b - rand(@ptnum) * (b - a));

if(chi("usedensityattrib"))
{
    string attrib = strip(chs("densityattrib"));
    float val = point(0, attrib, @ptnum);
    f@__density *= val;
}

vector dir = f@__pscale * normalize(v@N);

vector pos;
vector uvw;
int pr = intersect(1, v@P, dir, pos, uvw);
if(pr < 0)
    pr = intersect(1, v@P, -dir, pos, uvw);

if(pr < 0)
    removepoint(geoself(), @ptnum);
else
{
    float density = primuv(1, "__density", pr, uvw);
    if(density <= 0)
        removepoint(geoself(), @ptnum);
    else
    {
        i@__sourceprim = pr;
        v@__sourceprimuv = uvw;

        v@P = pos;
        v@N = primuv(1, "N", pr, uvw);
    }
}

f@__density = 1;
if(chs("coveragescalemode") == "attrib")
{
    string attrib = strip(chs("coverageattrib"));
    float val = point(0, attrib, @ptnum);
    f@__density = clamp(val, 0.0, 1.0);
}

f@__spacing = ch("spacing");
if(chs("spacingscalemode") == "attrib")
{
    string attrib = strip(chs("spacingattrib"));
    float val = point(0, attrib, @ptnum);
    f@__spacing *= val;
}
if(chi("useminspacing"))
{
    float limit = ch("minspacing");
    if(f@__spacing < limit)
        f@__spacing = limit;
}
f@__density /= f@__spacing * f@__spacing;

if(chi("usedensityattrib"))
{
    string attrib = strip(chs("densityattrib"));
    float val = point(0, attrib, @ptnum);
    f@__density *= val;
}

vector center, projdir;
int projtype;
center = prim(@OpInput1, "stroke_projcenter", @primnum);
projdir = prim(@OpInput1, "stroke_projdir", @primnum);
projdir = normalize(projdir);
projtype = prim(@OpInput1, "stroke_projtype", @primnum);

vector @stroke_orig = 0;
vector @stroke_dir = 0;
vector @stroke_uv = 0;
int @stroke_prim = -1;
int @stroke_hit = 0;

float dist = 0;
if (projtype < 4)
{
    vector raytoplane = @stroke_orig - center;
    float planedist = dot(raytoplane, projdir);
    @stroke_orig -= @stroke_dir * planedist / dot(@stroke_dir, projdir);
}
else
{
    // Intersect with geometry
    int     hitprim;
    float   hitu, hitv;
    vector  hitpos;
    // This is yucky, we must guess a max dist!
    float   maxdist = length(@stroke_orig - center);
    maxdist *= 100;
    vector  raydir = normalize(@stroke_dir);
    hitprim = intersect(@OpInput2, @stroke_orig, raydir * maxdist, hitpos, hitu, hitv);
    @P = hitpos;
    @stroke_hit = hitprim >= 0;
    @stroke_prim = hitprim;
    @stroke_uv.x = hitu;
    @stroke_uv.y = hitv;
}

void applyRamp(export float val; float outputmin; float outputmax)
{
    if(chi("useramp"))
        val = chramp("remap", val);
    val = fit(val, 0, 1, outputmin, outputmax);
}

float val = f@input;

float inputmin = ch("inputmin");
float inputmax = ch("inputmax");
float outputmin = ch("outputmin");
float outputmax = ch("outputmax");

int clamptype = chi("clamptype");

float denom = inputmax - inputmin;
if(denom == 0)
    val = (val < inputmin ? 0 : 1);
else if(clamptype == 0)
{
    // edge
    val = fit(val, inputmin, inputmax, 0, 1);
}
else if(clamptype == 1)
{
    // linear
    val = (val - inputmin) / denom * (outputmax - outputmin) + outputmin;
}
else // if(clamptype == 2)
{
    // cycle
    val -= inputmin;
    val /= denom;
    val -= floor(val);
}
if(clamptype != 1)
    applyRamp(val, outputmin, outputmax);

f@output = val;

int pt = nearpoint(1, v@P);
if(pt >= 0)
{
    vector p = point(1, "P", pt);
    f@dist = length(v@P - p);
}
else
    f@dist = -1;

vector p = point(1, "P", @ptnum);
vector v = v@P - p;
float d = length(v);
int metric = chi("distmetric");
int inside = point(2, "inside", @ptnum);
if(metric == 1)
{
    if(inside == 0)
        d = -d;
}
else // if(metric == 2)
{
    if(inside != 0)
        d = -d;
}
if(detail(3, "iteration") == 0 || (metric == 1 ? f@__dist < d : f@__dist > d))
    f@__dist = d;

/*
    INPUT 0: Scatter points
    INPUT 1: Geometry with "radii" attribute

    Creates two point groups:
    overlapping
    non_overlapping
*/

// Read radii from the first point of input 1
vector radii = point(1, "radii", 0);

// Horizontal footprint (X and Z)
float radius = length(set(radii.x, radii.z, 0));

float padding = chf("padding");
float min_dist = radius * 2.0 + padding;

// Find nearby scatter points
int nearpts[] = nearpoints(0, @P, min_dist);

int is_overlapping = 0;

foreach (int pt; nearpts)
{
    if (pt >= @ptnum)
        continue;

    vector otherP = point(0, "P", pt);
    vector delta = @P - otherP;

    float dist = length(set(delta.x, delta.z, 0));

    if (dist < min_dist)
    {
        is_overlapping = 1;
        break;
    }
}

setpointgroup(0, "overlapping", @ptnum, is_overlapping, "set");
setpointgroup(0, "non_overlapping", @ptnum, !is_overlapping, "set");

