int test_overlap(const int input; const vector P; const int curpt; const float pscale; const float tol)
{
    int npts = npoints(input);
    int closepts[] = pcfind_radius(input, "P", "__pscale", 1.0f, P, pscale, npts);
    foreach(int pt; closepts)
    {
        if(input == 0 && pt == curpt)
            continue;

        vector p1 = point(input, "P", pt);
        float pscale1 = point(input, "__pscale", pt);
        if(length(p1 - P) - pscale1 < (1 - tol) * pscale)
            return 1;
    }
    return 0;
}

float tol = ch("overlaptolerance");
if(test_overlap(0, v@P, @ptnum, f@__pscale, tol) == 1
    || test_overlap(1, v@P, @ptnum, f@__pscale, tol) == 1)
    removepoint(geoself(), @ptnum);

float a = ch("minradius");
