    f@__density *= val;
}

vector dir = f@__pscale * normalize(v@N);

vector pos;
vector uvw;
int pr = intersect(1, v@P, dir, pos, uvw);
if(pr < 0)
    pr = intersect(1, v@P, -dir, pos, uvw);

if(pr < 0)
    removepoint(geoself(), @ptnum);
else
{
    float density = primuv(1, "__density", pr, uvw);
    if(density <= 0)
        removepoint(geoself(), @ptnum);
    else
    {
        i@__sourceprim = pr;
        v@__sourceprimuv = uvw;

        v@P = pos;
        v@N = primuv(1, "N", pr, uvw);
    }
}

