/*
    INPUT 0: Scatter points
    INPUT 1: Geometry with "radii" attribute

    Creates two point groups:
    overlapping
    non_overlapping
*/

// Read radii from the first point of input 1
vector radii = point(1, "radii", 0);

// Horizontal footprint (X and Z)
float radius = length(set(radii.x, radii.z, 0));

float padding = chf("padding");
float min_dist = radius * 2.0 + padding;

// Find nearby scatter points
int nearpts[] = nearpoints(0, @P, min_dist);

int is_overlapping = 0;

foreach (int pt; nearpts)
{
    if (pt >= @ptnum)
        continue;

    vector otherP = point(0, "P", pt);
    vector delta = @P - otherP;

    float dist = length(set(delta.x, delta.z, 0));

    if (dist < min_dist)
    {
        is_overlapping = 1;
        break;
    }
}

setpointgroup(0, "overlapping", @ptnum, is_overlapping, "set");
setpointgroup(0, "non_overlapping", @ptnum, !is_overlapping, "set");

